package com.tekwatt.telemetry.controller;import com.tekwatt.telemetry.dto.*;import com.tekwatt.telemetry.service.TelemetryService;import jakarta.validation.Valid;import java.time.Instant;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/v1/telemetry/readings")public class TelemetryController{private final TelemetryService service;public TelemetryController(TelemetryService s){service=s;}@PostMapping@ResponseStatus(HttpStatus.CREATED)TelemetryResponse create(@Valid@RequestBody TelemetryRequest r){return service.create(r);}@PostMapping("/batch")@ResponseStatus(HttpStatus.CREATED)List<TelemetryResponse>batch(@Valid@RequestBody TelemetryBatchRequest r){return service.batch(r);}@GetMapping List<TelemetryResponse>history(@RequestParam UUID chargerId,@RequestParam(required=false)Instant from,@RequestParam(required=false)Instant to){return service.history(chargerId,from,to);}@GetMapping("/latest")List<TelemetryResponse>latest(@RequestParam UUID connectorId){return service.latest(connectorId);}}
